, supplier network, regulatory knowledge, specialized expertise -> /"], "company_type": "Contract manufacturer / job shop", "makes_products": "yes", "type_evidence": "Manufacturing is at the heart of what we do.", "founded_year": "", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='keystone-co-pack-manufacturing-llc' AND approved AND profile IS NULL;
